import { MAC_OS, WEBAPP_DOMAIN, WINDOWS_OS } from "../constants";
import Push from "./push";
import Notifications from "./notifications";
import { adminOverrides, colorConsole, getUserOS, buildIncomingMessageContextMessage } from "../app_utils"
import { getLocalizedAppString } from "./strings";
import ContextMenus from "./context-menus";

class Windows {
    static NOTIF_WINDOW_STORAGE_KEY = "notif_window_name"
    static TOS_PP_UPDATE_PROMPT_ID = "tos-pp-update-prompt"
    constructor(){
        this.listeners();
    }

    listeners(){
        const self = this;
        self.onRemovedListener();
        self.messageListeners();
    }

    messageListeners(){
        const self = this;
        chrome.runtime.onMessage.addListener(async (message, sender, sendResponse) => {        
            if(message.checkForExistingQRWindow){
                self.checkForExistingQRWindowForThisMsg(message)
                sendResponse({
                    received_in_windows: true,
                    ok: true
                })
            }
        });
    }

    onRemovedListener(){
        chrome.windows.onRemoved.addListener(function(removedWindowID){
            console.info("Removed window id", removedWindowID);
            //checking if this was a custom notif window
        
            const notifWindowFound = Windows.getNotifWindowMetadata(removedWindowID);
            // not sure if any of this is relevant.
            if(notifWindowFound && notifWindowFound.custom_mt_id_str == Windows.TOS_PP_UPDATE_PROMPT_ID){//notif window removed was for tos pp update may 2018.  Need to record an analytics event and set a jStorage to not display again for 2 days
                console.info("[TOS PP] tos pp consent window removed!");
                // recordTOSPPUpdateAnalyticsEvent({
                //     action: "remove"
                // });
                var doNotDisplayTOSPPWindowTTL = 2 * 24 * 60 * 60 * 1000;//2 days 5.30.18 KL
                $.jStorage.set("user-tos-pp-consent-prompt", "user-dismissed", {TTL:doNotDisplayTOSPPWindowTTL});
            }
        
        });
    }

    static setNotifWindowMetadata({windowId, metadata}){
        chrome.storage.local.set({
            category: Windows.NOTIF_WINDOW_STORAGE_KEY,
            id: windowId,
            ...metadata
        })
    }

    static getNotifWindowMetadata(windowId){
        return chrome.storage.local.get({
            category: Windows.NOTIF_WINDOW_STORAGE_KEY,
            id: windowId
        })
    }

    async checkForExistingQRWindow(threadURLPattern, threadIDSnippet){

        threadIDSnippet = String(threadIDSnippet);
    
        const tabs = await chrome.tabs.query({
            url: `${WEBAPP_DOMAIN}/*`
        });

        console.error(`[checkForExistingQRWindow] tabs`, tabs);
        console.error(`[checkForExistingQRWindow] threadIDSnippet`, threadIDSnippet);    
        //the chrome URL patterns was having an issue with our QR url, I was unable to figure out the correct pattern for the chrome.tabs.query function, so I built my own version.  We are looking for all mt tabs, and then essentially doing another loop here.
        const existingQRTabOrWindow = tabs.find(tab => tab.url.includes(threadIDSnippet))

        console.error(`[checkForExistingQRWindow] tab found?`, existingQRTabOrWindow);

        if (existingQRTabOrWindow){
            await chrome.windows.update(existingQRTabOrWindow.windowId, {focused: true})
            return false;
        }

        Windows.createInUpperRight(threadURLPattern);
        return true;
    }

    async checkForExistingQRWindowForThisMsg({msg, notif_details, not_active_in_qr_callback = () => {}, active_in_qr_callback = () => {}}){
        const self = this;
    
        if(
            (msg) &&
            (notif_details)
        ){
            if(            
                (msg.mms_wakeup)&&
                (msg.type != 11)
            ){//if this is an mms_wakeup CAPI, and it's NOT an incoming picture warning, then we should not bother with the window query because we only get the content author (full phone num) in the data payload, which would trigger a false positive if the user happened to be in that contact's individual thread.  And it is not identified in the 
                console.error("user is not active!!!")
                return self.checkIfThereIsAnExistingChromeNotifForThisConv({msg, notif_details})
            } 

            const threadIdSnippet = await Windows.threadIdSnippet(notif_details.id);
            const window = await chrome.windows.getLastFocused({
                populate: true//necessary to know the URL of the active Window
            })

            const alreadyFocusedInQRWindowForThisMsgThread = window.tabs.find(tab => tab.url.includes(threadIdSnippet))
            
            if(!alreadyFocusedInQRWindowForThisMsgThread){            
                return self.checkIfThereIsAnExistingChromeNotifForThisConv({msg, notif_details});
            } else {
                console.info("[checkForExistingQRWindowForThisMsg] thread ID's match! don't create a chrome notif!")
            }
            
            console.error("about to call active in qr callbackk!");
            active_in_qr_callback();        
        }
    }

    async checkIfThereIsAnExistingChromeNotifForThisConv({msg, notif_details: notifDetails}){
        if(!notifDetails){
            console.error("Missing notif details!");
            return false;
        }    
            
        const {phone_num_clean: threadIdOfCurrentIncomingMsg} = msg;
        const {msg_type: msgType} = notifDetails;
        let createNewNotif = false;
                    
        notifDetails = Object.assign(notifDetails, {phone_num_clean: threadIdOfCurrentIncomingMsg, msg_type: msg.type});
        
        console.error("notif details", notifDetails);
        const {id, notif_options} = notifDetails;
        const userOS = await getUserOS();

        if(
            (Push.isPic(msgType)) ||
            (Push.isCall(msgType))
        ){//picture & call notifs are never grouped
            const {id: uniqueNotifId, notif_options:notifOptions} = notifDetails;
            const createdId = await chrome.notifications.create(uniqueNotifId, notifOptions)

            // recordAnalyticsForIncomingMsgNotifCreation({origin: "new_chrome_notif_created", msg_type: sms.type});
            
            colorConsole("Just created a Incoming Message Notif at: "+ new Date() + "with the ID " + createdId, "green");
            
            Notifications.recordAnalyticsEvent({                
                type: 'notif-created',
                sub_type: msgType
            });
            
            // genericChromeNotifCreateCallback({
            //     notif_id: createdId,
            //     auto_dismiss: notifOncreateOptions.auto_dismiss,
            //     notif_sound: notifOncreateOptions.notif_sound
            // });

        } else {
            // Group consecutive messages from the same contact into one
            // updating notification. We read each currently-visible notif's
            // metadata directly in the service worker (it's keyed by notif id
            // and includes phone_num_clean = the thread id) and match on the
            // thread. If a visible notif exists for this contact we update it
            // in place; otherwise we create a new one.
            //
            // NOTE: the previous implementation referenced an offscreen-only
            // global (globalIncomingMsgThreadNotifDetailsObj) and read the
            // metadata response envelope incorrectly, so it always threw and
            // fell through to creating a fresh notif per message.
            const notifications = await chrome.notifications.getAll();
            const notifIDs = Object.keys(notifications);

            let existingThreadNotifId = null;
            for(const notifID of notifIDs){
                const md = await Notifications.getNotificationMetaData(notifID);
                if(
                    md &&
                    md.phone_num_clean === threadIdOfCurrentIncomingMsg &&
                    !Push.isPic(md.type) &&
                    !Push.isCall(md.type)
                ){
                    existingThreadNotifId = notifID;
                    break;
                }
            }

            if(existingThreadNotifId){
                const wasUpdated = await chrome.notifications.update(existingThreadNotifId, {
                    message: notifDetails.message,
                    contextMessage: buildIncomingMessageContextMessage({timestamp: msg.ts_server})
                });

                if(wasUpdated){
                    Notifications.recordAnalyticsEvent({
                        type: 'notif-updated',
                        sub_type: msgType
                    });
                } else {//the matched notif was already dismissed; create a fresh one
                    Notifications.createIncomingMessage(id, msgType, notif_options);
                }
            } else {//no visible notif for this contact; create a new one
                Notifications.createIncomingMessage(id, msgType, notif_options);
            }
        }
    }

    parseUrlParams(url) {
        const params = new URLSearchParams(url.split('?')[1]);
        const paramsObj = {};
        for (const [key, value] of params.entries()) {
            paramsObj[key] = value;
        }
        return paramsObj;
    }

    static async createInUpperRight(url){
        const checkIfAdminHasOverriddenWAPath = adminOverrides();//will return the path if overridden
        if(checkIfAdminHasOverriddenWAPath){
            colorConsole(`Warning: The webapp for this quick reply is loading from https://mightytext.net/${checkIfAdminHasOverriddenWAPath}`, "red");
        }

        console.error('[createInUpperRight] url:', url);

        const isQuickReply = url.includes('quick-reply');
        const userOS = await getUserOS();
        let {howWide, howHigh} = isQuickReply ? {howWide: 400, howHigh: 520} : { howWide: userOS === MAC_OS ? 500 : 516, howHigh: 600 };

        const displayInfo = await chrome.system.display.getInfo();
        const {bounds} = displayInfo.find((info) => info.isPrimary);
        const {width:availWidth} = bounds;
        // console.info("avail width", availWidth)
        let leftOffset = availWidth - (howWide + 7); // 7px buffer is good.

        // console.error("leftoffset",leftOffset)

        chrome.windows.create({
            url: url,
            left: parseInt(leftOffset),
            top: 0,
            width: howWide,
            height: howHigh,
            focused: true,
            type: "popup"
        }, async function(window) {

            //drawAttention is only valid on windows.update (NOT windows.create);
            //it's a best-effort flag for when the OS can't raise the window over
            //a fullscreen-Space app (e.g. macOS native fullscreen).
            chrome.windows.update(window.id,{focused:true, drawAttention:true});//make sure that this window is in focus even if the user is in another app

            const os = await getUserOS();
            if(os == WINDOWS_OS){//as of 8.16.18 we needed to implement this because Windows integrated Native Windows notifications and caused a bug where they would intermittently lose focus after being invoked from a buttonclick/notifclick event from the native notif. 
                setTimeout(function(){
                    chrome.windows.update(window.id,{focused:true})
                }, 250);
                setTimeout(function(){
                    chrome.windows.update(window.id,{focused:true})
                }, 500);
                setTimeout(function(){
                    chrome.windows.update(window.id,{focused:true})
                }, 1000);		
            }
        });

    }

    static async checkIfThereIsAlreadyAQuickReplyForThisThread(threadURLPattern, threadIDSnippet){

        threadIDSnippet = String(threadIDSnippet);
        
        const tabs = await chrome.tabs.query({
            url: ["https://mightytext.net/*", `${WEBAPP_DOMAIN}/*`]
        })

        console.error(`[checkIfThereIsAlreadyAQuickReplyForThisThread] tabs`, tabs);
        console.error(`[checkIfThereIsAlreadyAQuickReplyForThisThread] threadIDSnippet`, threadIDSnippet);    
        //the chrome URL patterns was having an issue with our QR url, I was unable to figure out the correct pattern for the chrome.tabs.query function, so I built my own version.  We are looking for all mt tabs, and then essentially doing another loop here.
        const existingQRTabOrWindow = tabs.find(tab => tab.url.includes(threadIDSnippet))

        console.error(`[checkIfThereIsAlreadyAQuickReplyForThisThread] tab found?`, existingQRTabOrWindow);

        if (existingQRTabOrWindow){
            await chrome.windows.update(existingQRTabOrWindow.windowId, {focused: true})        
            return
        }        

        Windows.createInUpperRight(threadURLPattern);    
    }
    
    static async quickReplyUrl(notifId){
        const isPictureNotif = notifId.includes('-picture');
        const notifIdToRetrieveData =  isPictureNotif ? notifId.replace('-picture','') : notifId;
        const notifMetadata = await Notifications.getNotificationMetaData(notifIdToRetrieveData);
        const {type: msgType , phone_num: phoneNum, phone_num_clean: phoneNumClean, id: msgId } = notifMetadata;
        console.error(`[quickReplyUrl] msgType: ${msgType}`);
        const threadIdSnippet = phoneNumClean;

        let quickReplyURL = isPictureNotif ? `${WEBAPP_DOMAIN}/#mode=quick&msgid=${msgId}` :
            Push.isCall(msgType) ? `${WEBAPP_DOMAIN}/#mode=quick&num=${phoneNum}` : 
            `${WEBAPP_DOMAIN}/quick/${phoneNumClean}/${msgId}`;
    
        if(!isPictureNotif)
            quickReplyURL += '&thread_id=' + threadIdSnippet;        

        return quickReplyURL;   
    }

    static async threadIdSnippet(notifId){
        const isPictureNotif = notifId.includes('-picture');
        const notifIdToRetrieveData =  isPictureNotif ? notifId.replace('-picture','') : notifId;
        const notifMetadata = await Notifications.getNotificationMetaData(notifIdToRetrieveData);

        const {phone_num_clean: phoneNumClean} = notifMetadata;
        
        // phone num clean is the thread id
        return phoneNumClean;
    }

    static async goToActiveMightyTextTab() {

        const tabsMatched = await chrome.tabs.query({
           currentWindow: true,
           url: [
            "https://mightytext.net/web*", 
            "https://mightytext.net/app*", 
            "https://beta.mightytext.net/*"
           ]
        })
    
        if(tabsMatched.length > 0){

            await chrome.tabs.update(tabsMatched[0].id, {active: true});

        } else {//no MT tabs found, create a new tab of the Web Application KL 5/9/14

            chrome.tabs.create({
                active: true,
                url: "https://beta.mightytext.net"
            }, function (){
                console.log("new tab of MightyText WebApp created.");
            });

        }
    };

    static async findActiveTabAndExecuteAnAction(action, optionalImgSrc){
        //This function is called when the user chooses a "web to phone" action from the popup menu.
        //Example:  They want to text the current URL of the page that they are viewing.
        const matchedTabs = await chrome.tabs.query({//These query params should find the user's active tab in their current window.
            currentWindow: true,
            active: true
        })
            //console.log(matched_tabs);
            
    //         console.error(matched_tabs);
        if(
            (Windows.checkForChromeTab({tabs: matchedTabs}))&&
            (action == "composeNew")
        ){//if true, we cannot inject our own content scripts into a chrome tab, so let's open compose new in a new tab 5.18.17 KL
            
            Windows.openNewTabOfWebAppInComposeNew();
            
        } else {

            var currentTab = matchedTabs[0];//there should only be 1 tab matched, since we are querying for the active tab in this window.
            let clickContext = ''
    
            //build the object that we are going to pass to the handleClick function
            let info = {
                editable: false,
                menuItemId: "context-menu-handle-page",
                pageUrl: currentTab["url"]
            };
    
            //If there is an img src passed to this function, then we want to add it into the object passed to the function to simulate a user's click of a context menu item
            if(optionalImgSrc){
                clickContext = "image";
                info["srcUrl"] = optionalImgSrc;
            } else {
            //If there isn't an img src argument
                clickContext = "link";
            }
    
            ContextMenus.handleClick({info, tab: currentTab, context: clickContext, bypassOM: true, actionToBypassTo: action})

        }
    };

    static checkForChromeTab({tabs}){
        if (!tabs) return false

        console.error("tabs", tabs);

        const chromeTab = tabs.find( tab => {tab.url.indexOf("chrome://")})

        return typeof chromeTab !== "undefined"
    }
    
    static openNewTabOfWebAppInComposeNew(){
        //If the user triggers "Compose New" from the popup menu on a chrome:// page, then we need to open a new tab with a url to the webapp in compose new mode because we are unable to inject a content script onto those pages.
        chrome.tabs.create({
            url: "https://mightytext.net/" + currentProductionPath + "#mode=compose-new"
        }, function(){
            console.log("new tab with webapp in compose new mode created");
        })
    };
}

export default Windows;