import {getLocalStorage, setLocalStorage} from "../app_utils.js";

class Settings {
    constructor(){
        this.listeners();
    }

    listeners(){
        const self = this;
        // listen for messages from other crx components
        chrome.runtime.onMessage.addListener(async (message, sender, sendResponse) => {
            if (message.getConsoleSettings){
                self.consoleSettings();
                sendResponse({
                    ok: true
                })
            } else if (message.setLocalStorage){
                const {key, value, ttl} = message;

                await setLocalStorage({key, value, ttl});

                sendResponse({
                    ok: true,
                    updatedKey: key,
                    updatedValue: value
                })
            } else if (message.getAppVersion){
                sendResponse({
                    appVersion: chrome.runtime.getManifest().version
                })
            } else if (message.getLocalStorage){
                console.error("received message to get localStorage!!!!")
                const {key} = message;
                const value = await getLocalStorage({key: key})
                sendResponse({
                    value: value
                })
            }

        });

        // listen for changes to chrome storage
        chrome.storage.onChanged.addListener(function(settingsObj, settingName){
            if(settingName === "debug_mode"){
                self.applyLoggingPreference(settingsObj.debug_mode.newValue);
            }
        });
    }

    async consoleSettings(){
        const self = this;
        const settings = await chrome.storage.local.get(null);
        
        if(settings.debug_mode){
            self.applyLoggingPreference(settings.debug_mode);
        }

        // set default logging preference if it hasn't been set.
        chrome.storage.local.set({
            debug_mode: "console_off"
        }, function(setting){
            console.log(setting);
        });                  
    }

    applyLoggingPreference(value){
        if(value == "console_off"){        
            //         console.log("consoles turned off");
            console.info = function(){};
            console.log = function(){};    
            return;    
        }
    
        console.info = origConsoleFunctionality.info;
        console.log = origConsoleFunctionality.log;
    }

    async setLocalStorage({key, value, ttl}){
        let storageValue = value;
        // jstorage TTL replication
        if (ttl){
            storageValue = {
                tsExpiration: new Date().getTime() + ttl,
                value: value
            }
        }

        await chrome.storage.local.set({
            [key]: storageValue
        })
    }
}

export default Settings;