export const getLocalizedAppString = ({key, placeholders = []}) => {
    let string = "*** Error in localization string function ***";
    if(key){
        var localizedString = chrome.i18n.getMessage(key);
        
        if(placeholders.length > 0){
            localizedString = chrome.i18n.getMessage(key, placeholders);
        }
        
        if(localizedString.length > 0){
            string = localizedString;
        } else {
            //the key was not found in the localization file(s)
            string = `*** Error: Localization string not found for key: "${key}" ***`;
        }	
    } else {
        console.error(new Date() + "Error in custom localization string function");
    }
    return string;
}