import { SIGNIN_URL_CRX, MAC_OS, WINDOWS_OS } from "../constants.js"
import { getUserOS, forceReloadCRX } from "../app_utils.js"
import { getLocalizedAppString } from "./strings.js"
import Windows from "../lib/windows.js"

class MessagesHub {
    constructor(){
        // MV3 service workers only treat a synchronous `return true` from the
        // listener as "keep the message channel open for an async response".
        // An async listener returns a Promise that the runtime ignores, so
        // sendResponse fires after the channel closes and the caller gets
        // `undefined`. Dispatch the async work in an IIFE and always return
        // true so async branches (getUserGlobalOS, getLocalizedString, …)
        // actually deliver their reply.
        // The keys this listener actually handles. We must only return `true`
        // (keep the channel open) for these — returning true for EVERY message
        // makes this listener claim the response channel for messages handled
        // by other listeners / the offscreen document, so their sendMessage
        // callbacks receive a null response and throw "Error handling response".
        const HANDLED_KEYS = [
            "loginNeeded",
            "new_notify_background_that_user_is_logged_in",
            "notify_crx_from_webapp_signin",
            "setProperBrowserActionIcon",
            "reloadCRX",
            "userClickedClearContactsButton",
            "handle_gcm_error",
            "get_username_prefix",
            "user_loaded_phone_notif_live_view",
            "check_user_pro_status",
            "user_consented_to_tos_pp_update",
            "record_mt_stats_event",
            "getUserGlobalOS",
            "getLocalizedString",
            "launchMT",
            "openComposeNew"
        ];

        chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
            if(!message || typeof message !== "object") return;//not ours
            const willHandle = HANDLED_KEYS.some((key) => message[key] !== undefined);
            if(!willHandle) return;//let other listeners / the offscreen doc respond

            (async (message, sender, sendResponse) => {
            if(message.loginNeeded){
                chrome.tabs.create({
                    url:SIGNIN_URL_CRX
                }, function(){
                    console.log("new tab of signInURL created");
                });
                sendResponse({
                    ok: true,
                    pageCreated: true
                })
            } else if(message.new_notify_background_that_user_is_logged_in){

                forceReloadCRX("User-Signed-In-From-CRX");
    
                sendResponse({reply:'successful_user_login'});
    
            } else if (message.notify_crx_from_webapp_signin){
    
                checkUserLoginStatusAfterPUSHNotifyLogout(true);
    
                sendResponse({reply:'notify_crx_from_webapp_signin'});
    
            } else if (message.setProperBrowserActionIcon){
    
                setBrowserActionIcon("user-logged-in");
    
                sendResponse({reply:'setting_browser_action_icon'});
    
            } else if (message.reloadCRX){
    
                forceReloadCRX(message.reloadReason);
    
                sendResponse({reply: "reloading_crx_now"});
    
            } else if (message.userClickedClearContactsButton){
    
                sendOtherC2DM("push_phone_contacts_to_cloud", "na", "user-clicked-clear-contacts-button-so-flush-jstorage");
    
                sendResponse({reply: "request_made_phone"});
    
            } else  if (message.handle_gcm_error){//message handler for GCM errors
                var responseObj;
    
                if((message.hasOwnProperty("details")) && (message.details.hasOwnProperty("action")) && (message.details.hasOwnProperty("server_resp"))){
                    responseObj = {
                        received_request_to_handle_gcm_error: true
                    };
    
                    var action = message.details.action,
                        serverResponse = message.details.server_resp;
    
                    handleC2DM_GCM_Errors(action, serverResponse);
    
                } else {
                    console.error(request);
                    responseObj = {
                        error_with_message_to_handle_gcm_errors: true
                    };
                }
    
                sendResponse(responseObj);
            } else if (message.hasOwnProperty("get_username_prefix")){
                sendResponse({username_prefix: username_prefix_jstrg_purpose});
            } else if (message.hasOwnProperty("user_loaded_phone_notif_live_view")){
                //this should only be triggered from the crx main popup menu
                checkIfUserHasAHealthyPUSHSocket();
            } else if (message.hasOwnProperty("check_user_pro_status")){
                // chrome.storage.local.get returns an object ({is_pro: <bool>}),
                // not the bare value — unwrap it so the popup's strict
                // `user_is_pro === false` check works and "Go Pro" can show.
                const { is_pro = false } = await chrome.storage.local.get('is_pro');
                sendResponse({user_is_pro: is_pro === true});
            } else if(message.hasOwnProperty("user_consented_to_tos_pp_update")){
                console.info(request);
                recordUserTOSPPConsent(request);
                recordTOSPPUpdateAnalyticsEvent({action: "consent", ip_info: message.ip_info});
            } else if (message.hasOwnProperty("record_mt_stats_event")){ 
                if("notif_event" in request){
    
                    recordNotificationAnalyticsEvent({
                        options: message.event_options
                    });
    
                } else {
                    //we aren't using this for anything other than a single notif event triggered from popup.js for now.  Not wiring anything in this else condition just yet 8.24.18 KL
                }
                sendResponse({rcvd_request_to_record_mt_event: true})
            } else if(message.getUserGlobalOS){
                const userOS = await getUserOS();

                sendResponse({
                    ok: true,
                    os: userOS 
                })
            } else if (message.getLocalizedString){
                const {key, placeholders} = message;
                sendResponse({
                    string: getLocalizedAppString({key, placeholders})
                })  
            } else if(message.launchMT){
                console.error('received message to launch MT!');
                sendResponse({
                    launching_MT: true
                });
                try{
                    Windows.goToActiveMightyTextTab();
                } catch(err){
                    console.error("Error launching MT");
                }
            } else if(message.openComposeNew){
                Windows.findActiveTabAndExecuteAnAction("composeNew");
                sendResponse({
                    opening_compose_new: true
                });
            }
            })(message, sender, sendResponse);
            return true;
        });
    }
}

export default MessagesHub;