import { colorConsole, userNotLoggedInBrowserActionClicked, checkRegularInternetConnection, forceReloadCRX } from "./app_utils.js";
import { GLOBAL_SYSTEM_IDLE_STATUS_THRESHOLD_IN_SECONDS } from "./constants.js"
import ContextMenus from "./lib/context-menus.js";
import MessagesHub from "./lib/messages.js";
import Notifications from "./lib/notifications.js";
import Settings from "./lib/settings.js";
import Windows from "./lib/windows.js"

class App {
    constructor(){
        console.error(`App starting...`);
        const self = this;
        
        self.globalLastKnownSystemStatus = "unknown"

        self.setupOffScreenDocument();

        self.messages = new MessagesHub();
        self.settings = new Settings();
        self.notifications = new Notifications();
        self.context_menus = new ContextMenus();
        self.windows = new Windows();
        self.setSystemIdleMonitor();
        self.listeners();
    }

    listeners(){
        const self = this;

        chrome.runtime.onMessage.addListener(async (message, sender, sendResponse) => {
            if(message.startSystemStatusTracker){
                self.setGlobalLastKnownSystemStatus();
            } else if (message.setIcon){
                const {options} = message;
                chrome.action.setIcon(options);
                sendResponse({
                    ok: true
                })
            } else if (message.setTitle){
                const {options} = message;
                chrome.action.setTitle(options);
                sendResponse({
                    ok: true
                })
            } else if (message.setPopup){
                const {options} = message;
                chrome.action.setPopup(options);
                sendResponse({
                    ok: true
                })
            } else if (message.setUserNotLoggedInBrowserActionOnClick){
                chrome.action.onClicked.removeListener(userNotLoggedInBrowserActionClicked);//remove any existing click handlers that is calling this function 9/30/14 KL
                chrome.action.onClicked.addListener(userNotLoggedInBrowserActionClicked);
            } else if (message.backupBrowserActionIconChecker){
                self.backupBrowserActionIconChecker();
                sendResponse({
                    ok: true
                })
            } else if (message.type === 'storage') {            
                switch (message.action) {
                    case 'get':
                        chrome.storage.local.get(message.key, (result) => {
                            const storedData = result[message.key];
                            if (storedData && storedData.timestamp && storedData.ttl) {
                                const age = Date.now() - storedData.timestamp;
                                if (age < storedData.ttl) {
                                    sendResponse({ [message.key]: storedData.value });
                                } else {
                                    // Data is too old, remove it and return nothing
                                    chrome.storage.local.remove(message.key);
                                    sendResponse({});
                                }
                            } else if (storedData && !storedData.ttl) {
                                // If no TTL, just return the value
                                sendResponse({ [message.key]: storedData.value });
                            } else {
                                sendResponse({});
                            }
                        });
                        break;
                    case 'set':
                        const key = Object.keys(message.data)[0];
                        const value = Object.values(message.data)[0];

                        // First check if we already have this key with a valid timestamp
                        chrome.storage.local.get(key, (result) => {
                            const existingData = result[key];
                            const now = Date.now();
                            
                            let timestamp;
                            let ttl = message.ttl;  // might be undefined

                            if (existingData && existingData.timestamp && existingData.ttl) {
                                const age = now - existingData.timestamp;
                                if (age < existingData.ttl) {
                                    // Use existing timestamp and TTL if still valid
                                    timestamp = existingData.timestamp;
                                    ttl = existingData.ttl;
                                } else {
                                    // Set new timestamp if expired
                                    timestamp = ttl ? now : undefined;
                                }
                            } else if (ttl) {
                                // Only set timestamp if we have a TTL
                                timestamp = now;
                            }

                            const dataWithTimestamp = {
                                [key]: {
                                    value: value,
                                    ...(timestamp && { timestamp }),
                                    ...(ttl && { ttl })
                                }
                            };
                            
                            chrome.storage.local.set(dataWithTimestamp, () => {
                                sendResponse({ success: true });
                            });
                        });
                        break;
                    case 'remove':
                        chrome.storage.local.remove(message.key, () => {
                            sendResponse({ success: true });
                        });
                        break;
                }
                return true; // Required to use sendResponse asynchronously
            }
        });
    }

    setSystemIdleMonitor(){
        const self = this;
        chrome.idle.setDetectionInterval(GLOBAL_SYSTEM_IDLE_STATUS_THRESHOLD_IN_SECONDS);//setting the threshold for an "idle" status to be triggered by the chrome.idle API.  We think it looks at mouse movements AND keypresses

        chrome.idle.onStateChanged.addListener((newSysStatus) => {
            if((newSysStatus == "active") && (self.globalLastKnownSystemStatus == "locked")){//if the current system status is "active", and the last known system status was "locked, then we need to clear all notifications in the tray that were created during the locked state. 3/5/15 KL
                // this will need to be refactored into it's own class
                self.notifications.clearStaleLocked();

                colorConsole("the system was locked, but became active", "orange");
            }

            self.globalLastKnownSystemStatus = newSysStatus;//update the global system status indicator

            colorConsole("System status changed to: " + newSysStatus + " at: "+ new Date(), "orange");
        });
    }

    setGlobalLastKnownSystemStatus(){
        const self = this;
        chrome.idle.queryState(GLOBAL_SYSTEM_IDLE_STATUS_THRESHOLD_IN_SECONDS, function(currentSystemState){//if the user has been inactive for 60 seconds, then they will be considered IDLE
            //this 60 seconds threshold is also set in a separate
    
            colorConsole("Setting var globalLastKnownSystemStatus to: \"" + currentSystemState + "\"", "purple");
    
            self.globalLastKnownSystemStatus = currentSystemState;
    
        });    
    }

    async backupBrowserActionIconChecker(){
        const status = await chrome.action.getTitle({});

        let currentBrowserActionStatus = status;
        colorConsole("Inside of backupBrowserActionIconChecker. Current BA tooltip content: "+ currentBrowserActionStatus, "#FF8DC6", "14px");

        //the string that we are looking for below will eventually have to reference a localized string function. Example if the user's language setting is set to "FR", we will need to look for the string "Se il vous plaît vérifier votre connexion Internet"
        if(currentBrowserActionStatus.includes("Please check your internet connection")){
        //This means there is currently a grey browseraction icon.  This tells the user that they do not have an internet connection

            colorConsole("BA indicates user has no internet connectivity.  Confirming...", "#FF8DC6", "14px");

            if(!navigator.onLine){

                return false;

            } else {
                //If the user has a network connection, we should check if they have an internet connection, if so we need to reload the extension.
                checkRegularInternetConnection(function(){forceReloadCRX("Browser-Action-Incorrect-No-Int")});

            }

        } else if (currentBrowserActionStatus.indexOf("Not Logged In") > -1){
            //the current browser action indicates that they're not logged in, but if the user as lost their internet connection then we should reload the CRX.

            colorConsole("BA indicates user is not signed into MT.  Confirming that they have internet connectivity.", "#FF8DC6", "14px");

            if(!navigator.onLine){
                //If we detect that the user's network connection is off, then we should make sure that the browser action icon accurately reflects that they don't have a network connection (and no internet)
                forceReloadCRX("Browser-Action-Not-Logged-In-Wrong");

            } else {

                //The second parameter passed to this checkRegularInternetConnection function will only be executed if we determine the user's internet connection is broken.
                checkRegularInternetConnection("", function(){forceReloadCRX("Browser-Action-Incorrect-Not-Logged-In")});

            }

        }
    }

    async setupOffScreenDocument() {
        const persistentOffScreenDocumentUrl = chrome.runtime.getURL('/html/background.html');
        
        try {
            // Get all existing offscreen documents
            const existingContexts = await chrome.runtime.getContexts({
                contextTypes: ['OFFSCREEN_DOCUMENT']
            });
            
            // Reuse the live offscreen document if there is one. The MV3
            // service worker is killed and respawned constantly (idle ~30s),
            // and the offscreen doc survives those deaths — recreating it on
            // every SW wake re-boots the entire legacy app (getUserInfoFull,
            // push socket, mt-logger) dozens of times a day per user.
            if (existingContexts.length > 0) {
                console.log('Offscreen document already exists; reusing it');
                return;
            }

            // Create new offscreen document
            await chrome.offscreen.createDocument({
                url: persistentOffScreenDocumentUrl,
                reasons: ['WEB_RTC', 'AUDIO_PLAYBACK'],//AUDIO_PLAYBACK is needed so the offscreen doc can play notification sounds (the service worker can't)
                justification: 'Maintain a persistent WebSocket connection for push notifications and play notification sounds.'
            });
            
            console.log('Offscreen document created successfully');
        } catch (error) {
            console.error('Error managing offscreen document:', error);
        }
    }
}

const app = new App();