import { getLocalizedAppString } from "./strings.js"
import { fixedEncodeURIComponent } from "../app_utils.js"
import { BASE_URL } from "../constants.js";

class ContextMenus{
    static AUTO_DISMISS_STORAGE_KEY = "notif_auto_dismiss"
    static MENU_ID_HANDLE_IMAGE = 'context-menu-handle-image';
    static MENU_ID_HANDLE_PAGE = 'context-menu-handle-page';
    static MENU_ID_HANDLE_SELECTION = 'context-menu-handle-selection';
    static MENU_ID_OPEN_MT = 'browser-action-cmenu-open-mt';
    static MENU_ID_COMPOSE_NEW = 'browser-action-cmenu-compose-new';
    static ACTION_SEND_TO_PHONE = 'send-to-phone';
    static ACTION_COMPOSE_NEW = 'compose-new';
    static ACTION_SEND_MESSAGE = 'send-message';

    constructor(){
        this.listeners();
        this.set();//register context menus at SW startup so right-click works without waiting for the legacy login flow
    }

    listeners(){
        const self = this;

        //Register the context-menu click handler ONCE, at startup. handleClick
        //is a static method, so it must be invoked on the class. The previous
        //code registered it inside set() and called self.handleClick (undefined
        //on the instance), which is why right-click did nothing.
        chrome.contextMenus.onClicked.addListener((info, tab) => {
            ContextMenus.handleClick({tab, info});
        });

        chrome.runtime.onMessage.addListener(async (message, sender, sendResponse) => {
            if (message.createContextMenus){
                self.set();
                sendResponse({
                    ok: true
                })
            } else if (message.sendContentToPhone){
                self.syncToPhone(message.action_data);
                sendResponse({
                    confirmation: {
                        requestToSendImg: true
                    }
                });
            } else if (message.removeAllContextMenus){
                await chrome.contextMenus.removeAll();
                sendResponse({
                    ok: true
                })
            }
        });
    }

    async set(){
        const self = this;
        await chrome.contextMenus.removeAll()
        chrome.contextMenus.create({
            id: ContextMenus.MENU_ID_HANDLE_IMAGE,
            title: getLocalizedAppString({key: "send_img_with_mt"}),
            type: "normal",
            contexts: ["image"],
        });

        chrome.contextMenus.create({
            id: ContextMenus.MENU_ID_HANDLE_PAGE,
            title: getLocalizedAppString({key: "send_page_with_mt"}),
            type: "normal",        
        });

        chrome.contextMenus.create({
            id: ContextMenus.MENU_ID_HANDLE_SELECTION,
            title: getLocalizedAppString({key: "send_selection_with_mt"}),
            type: "normal",
            contexts: ["selection"],
        });
                        
        chrome.contextMenus.create({
            id: ContextMenus.MENU_ID_OPEN_MT,
            title: getLocalizedAppString({key: "open_mightytext"}),
            type: "normal",
            contexts: ["browser_action"],
        });
        
        chrome.contextMenus.create({
            id: ContextMenus.MENU_ID_COMPOSE_NEW,
            title: getLocalizedAppString({key: "compose_new"}),
            type: "normal",
            contexts: ["browser_action"],
        });
    }

    static async handleClick({tab, info, context, bypassOM, actionToBypassTo}){
        const {menuItemId, frameUrl} = info;

//are the user's trying to interact inside of another iFrame? If so, is it an MT iframe? Are they trying t trigger another overlay ontop of an existing one? Don't let them.
        if(frameUrl && frameUrl.includes("mightytext.net")) return false

        //carry the click context (image/link/selection) through to the send path
        if(context) info = {...info, context};

        //1) make sure the web-to-phone content script is present in this tab
        let contentScriptExists = false;
        try{
            const response = await chrome.tabs.sendMessage(tab.id, {//ask the tab whether our content script is already injected
                webToPhoneJSTestMessage: true
            });
            contentScriptExists = !!(response && response.content_script_exists);
        } catch(e){
            contentScriptExists = false;//no content script (or no listener) in this tab yet
        }

        if(!contentScriptExists){
            //inserting CSS assets needed for send to phone widget
            chrome.scripting.insertCSS({
                target: { tabId: tab.id },
                files: [
                    "styles/font-awesome-4.2.0/css/font-awesome.css",
                    "styles/material-icons/material-font.css",
                    "styles/animate.css",
                    "styles/bootstrap-alert-css-only/css/bootstrap-custom.css",
                    "styles/web_to_phone.css"
                ]
            });

            //insert JS assets needed for send to phone widget
            await chrome.scripting.executeScript({
                target: { tabId: tab.id },
                files: [
                    "scripts/libs/jquery-2.1.0.min.js",
                    "scripts/libs/bootstrap-growl-master/bootstrap-growl.min.js",
                    "scripts/libs/jQuery.dotdotdot-1.6.14/src/js/jquery.dotdotdot.min.js",
                    "scripts/common.js",
                    "scripts/web_to_phone.js"
                ]
            });
        }

        //2) dispatch exactly once. Page/selection actions shorten the URL first
        //(used to build the compose-new body); image and compose-new-from-the-
        //browser-action go straight to the content script.
        if([ContextMenus.MENU_ID_HANDLE_SELECTION, ContextMenus.MENU_ID_HANDLE_PAGE].includes(menuItemId)){
            ContextMenus.shortenContextURLThenBuildIframeURL({contextInfo: info, tabId: tab.id, bypassModal: bypassOM, desiredAction: actionToBypassTo});
        } else {
            ContextMenus.sendClickInfoToContentScript({info, tabId: tab.id, bypassModal: bypassOM, intendedAction: actionToBypassTo});
        }
    }

    static async shortenContextURLThenBuildIframeURL({contextInfo, tabId, bypassModal = false, desiredAction}) {
        // Clone the contextInfo object
        const modifiedContextInfo = { ...contextInfo };
        const encodedURL = encodeURIComponent(modifiedContextInfo.pageUrl);
        const url = `https://mightytext.net/prod-assets/bitly/shorten-link.php?url=${encodedURL}`;

        try {
            const response = await fetch(url);
            const reply_server = await response.text();
            const cleanedResponse = reply_server.replace(/\\"/g, '"');
            console.info('[bitly shortlink response]', cleanedResponse);
            
            const responseJSON = JSON.parse(cleanedResponse);
            console.log(responseJSON);
            
            modifiedContextInfo.shortUrl = responseJSON.data?.url 
                ? responseJSON.data.url.replace("http://", "")
                : modifiedContextInfo.info.pageUrl;

            console.log('Modified context info:', modifiedContextInfo);
            ContextMenus.sendClickInfoToContentScript({
                info: modifiedContextInfo, 
                tabId, 
                bypassModal, 
                intendedAction: desiredAction
            });
            
        } catch (error) {
            console.error('Error in C2DM:', error);
            console.error('Error details:', error.message);
            
            modifiedContextInfo.shortUrl = modifiedContextInfo.pageUrl;
            ContextMenus.sendClickInfoToContentScript({
                info: modifiedContextInfo, 
                tabId, 
                bypassModal, 
                intendedAction: desiredAction
            });
        }
    }

    static async sendClickInfoToContentScript({info, tabId, bypassModal, intendedAction}){
        console.log("inside of sendclickinfotocontentscript");
    
        const messageObj = {
            contextMenuInfo: {
                ...info,
                tab: await chrome.tabs.get(tabId)
            },
            ...(bypassModal && {
                bypassOptionsModal: true,
                task: intendedAction
            })
        };
    
        console.log({
            tabid: tabId,
            message: messageObj
        });
    
        chrome.tabs.sendMessage(tabId, messageObj);
    }

    syncToPhone(info){
        const self = this;

        console.log('syncToPhone', info);
        let body,
            action,
            actionData;
        if(info.context == "image"){
            body = " ";
            action = "fetch_binary_from_url_store_on_device";
            actionData = body + "||" + info.srcUrl;
        } else if (info.context == "link"){
            var pageTitle = fixedEncodeURIComponent(info.tab.title);
            var pageUrl = fixedEncodeURIComponent(info.pageUrl);
            action = "launch_from_url";
            actionData = pageUrl + "|||" + pageTitle;
        } else if (info.context == "selection"){
            action = "send_snippet_to_phone";
            actionData = info.info.selectionText;
        }
    
    //     encoded_action_data = encodeURIComponent(action_data);//KL is encoding this data because of the "fetch_binary_from_url_store_on_device" action.  The img src that is sent would sometimes have url params, but that would be INCORRECTLY interpreted as a post param in the ajax made in sendOtherC2DM
        //we are encoding all url params, not just action_data, in the sendOtherC2DM function now 9.5.17 
    
        self.sendOtherC2DM(action, actionData, null, info.tab.id);
    }

    // Timeout wrapper function
    fetchWithTimeout(url, options, timeout = 8000) {
        return Promise.race([
            fetch(url, options),
            new Promise((_, reject) => 
                setTimeout(() => reject(new Error('Request timed out')), timeout)
            )
        ]);
    }

    async sendOtherC2DM(action, actionData, extraParamOptional, tabIdOptional) {
        const self = this;
        const sendUrl = BASE_URL + "/client";
        
        const postData = {
            "function": "send",
            "deviceType": "ac2dm",
            "source_client": 32,
            "action": action,
            "action_data": actionData
        };

        if (extraParamOptional) {
            postData.extra_param = extraParamOptional;
        }

        console.log('send url for Custom C2DM is: ' + sendUrl);
        console.log('post vars string: ', postData);

        try {
            const response = await self.fetchWithTimeout(
                sendUrl, 
                {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded',
                    },
                    body: new URLSearchParams(postData)
                },
                8000
            );

            const reply_server = await response.text();
            
            // Record successful response time
            // time_last_success_mighty_ping = new Date();

            if (reply_server.includes("sent to phone")) {
                if (["fetch_binary_from_url_store_on_device", "launch_from_url", "send_snippet_to_phone"].includes(action)) {
                    // Track success in both KM and GA
                    let context = '';
                    if (action === "fetch_binary_from_url_store_on_device") {
                        context = "image";
                    } else if (action === "launch_from_url") {
                        context = "link";
                    } else if (action === "send_snippet_to_phone") {
                        context = "selection";
                    }

                    self.alertWeb2PhoneOfSendC2DMSuccess(tabIdOptional, true);

                } else if (action === "push_phone_contacts_to_cloud") {
                    if (extraParamOptional === "user-clicked-clear-contacts-button-so-flush-jstorage") {
                        self.notifyOptionsPageOfContactRefreshResponse(true);
                    }
                }
            } else {
                // Handle non-success responses
                if (["fetch_binary_from_url_store_on_device", "launch_from_url", "send_snippet_to_phone"].includes(action)) {
                    self.alertWeb2PhoneOfSendC2DMSuccess(tabIdOptional, false);
                } else if (action === "push_phone_contacts_to_cloud") {
                    if (extraParamOptional === "user-clicked-clear-contacts-button-so-flush-jstorage") {
                        self.notifyOptionsPageOfContactRefreshResponse(false);
                    }
                }
                // come back
                // handleC2DM_GCM_Errors(action, reply_server);
            }

        } catch (error) {
            console.error('Error in C2DM:', error);
            console.error('Error details:', error.message);

            // Handle network/fetch errors
            if (["fetch_binary_from_url_store_on_device", "launch_from_url", "send_snippet_to_phone"].includes(action)) {
                self.alertWeb2PhoneOfSendC2DMSuccess(tabIdOptional, false);
            } else if (action === "push_phone_contacts_to_cloud") {
                if (extraParamOptional === "user-clicked-clear-contacts-button-so-flush-jstorage") {
                    self.notifyOptionsPageOfContactRefreshResponse(false);
                }
            }
        }
    }

    alertWeb2PhoneOfSendC2DMSuccess(tabId, success){
        chrome.tabs.sendMessage(tabId, {//SEND MESSAGE TO THE CONTENT SCRIPT WE JUST INSERTED WITH THE CLICK EVEN INFO
            sendC2DMStatus: true,
            response_status: success
        }, function(response) {
            console.log(response);
        });
    }

    notifyOptionsPageOfContactRefreshResponse(responseStatus){
        chrome.runtime.sendMessage({
            refreshContactsFromPhoneC2DMSent: true,
            status:responseStatus
        }, function(response){
            console.log(response);
        });
    }
}

export default ContextMenus