import {MAC_OS, NOTIFICATION_SUFFIX, WINDOWS_OS, SIGNIN_URL_CRX} from "./constants.js"
import Analytics from "./lib/analytics.js";
import { format } from 'date-fns';
const OVERRIDABLE_KEYS = ["webapp_path_override"];
export function forceReloadCRX (label) {
    // add analytics for the label
    // reload the extension
	Analytics.recordEvent({
		options:{
			type: 'app-reload',
			sub_type: label
		}
	})
	chrome.runtime.reload();
}


export function checkInternetConnectionOutbound(nextFunctionAfterNetworkSuccess){

	console.log('--------Checking outbound internet connection');

	// Third-party probe (not our server) — see comments in
	// scripts/background.js for rationale. Cloudflare's trace endpoint
	// sends Access-Control-Allow-Origin: * so we need no host_permissions.
	fetch("https://cloudflare.com/cdn-cgi/trace", { cache: "no-store" })
		.then(response => {
			if (response.ok) {
				console.info("Outbound connectivity ping...success");
				nextFunctionAfterNetworkSuccess();
			} else {
				console.info("Outbound connectivity ping...failed");
			}
		})
		.catch(() => {
			console.error("Outbound connectivity ping...failed");
		});

}

export async function checkRegularInternetConnection(callbackIfSuccessConnected, optionalCallbackOnAjaxError) {
    // Third-party probe (not our server) — see comments in
    // scripts/background.js for rationale.
    const probeUrl = "https://cloudflare.com/cdn-cgi/trace";
    try {
        const response = await Promise.race([
            fetch(probeUrl, {
                method: 'GET',
                cache: 'no-store',
            }),
            new Promise((_, reject) =>
                setTimeout(() => reject(new Error('Request timed out')), 8000)
            )
        ]);

        if (response.ok) {
            colorConsole("CheckRegularInternetConnection succeeded!", "#74AAD8", "14px");

            if (callbackIfSuccessConnected) {
                callbackIfSuccessConnected();
            }
        } else {
            throw new Error('Network response was not ok');
        }
    } catch (error) {
        if (optionalCallbackOnAjaxError) {
            optionalCallbackOnAjaxError();
        }

        colorConsole(
            "Error: Unable to fetch " + probeUrl + " — likely an internet connectivity issue",
            "#74AAD8",
            "14px"
        );
    }
}

export function colorConsole(str, color, size){
    
    let finalColor;
    let finalSize;

    if(color)
        finalColor=color;
    else
        finalColor='blue';
    if(size)
        finalSize=size;
    else
        finalSize='large';
        
    console.log("%c" + str, "color: " + finalColor + ";font-size: " + finalSize);    
        
}

export function adminOverrides(){
    let check = false;
	
	OVERRIDABLE_KEYS.forEach(async (item) => {
		const value = chrome.storage.local.get(item);
		
		if(value){
			if(item == "webapp_path_override"){				
				if(
					(typeof data != "undefined")&&
					(data.hasOwnProperty("found_callback"))
				){
					data.found_callback({override_value: value});
				}
				check = value;
			}			
		}
	});
	
	return check;//return boolean about whether the override was found
}

export async function getUserOS(){
	const {os} = await chrome.runtime.getPlatformInfo();
	let userOS = 'unknown';

	if(os === "mac"){
		userOS = MAC_OS;
	} else if (os === "win"){
		userOS = WINDOWS_OS;//confirmed this is the string output of the BrowserDetect js lib we used in the webapp
	}

	return userOS;
}

export function fixedEncodeURIComponent(str) {
    return encodeURIComponent(str).replace(/[!'()]/g, escape).replace(/\*/g, "%2A");
};

export async function determineIfNotifShouldRequireInteractionBasedOnOS({notifOptions}){
	// cloning options input
	let options = JSON.parse(JSON.stringify(notifOptions));
	
	if(await getUserOS() != "Mac"){
		options.requireInteraction = true;
	}

	return options;
}

export async function getLocalStorage({key}){
	let value = await chrome.storage.local.get(key);

	// jstorage TTL replication
	try{
		const {tsExpiration} = value;
		if(tsExpiration){
			const nowInMs = new Date().getTime();
			// value has expired.   return "undefined"
			if (nowInMs > tsExpiration){
				value = undefined;
				chrome.storage.local.remove(key);
			}
		}
	} catch(e){
		console.info(`Stored value with key: "${key}" could not be parsed`, e);
	}
	console.error("returning value", value);
	
	return value;
}

export async function setLocalStorage({key, value, ttl}){
	let storageValue = value;
	// jstorage TTL replication
	if (ttl){
		storageValue = {
			tsExpiration: new Date().getTime() + ttl,
			value: value
		}
	}

	await chrome.storage.local.set({
		[key]: storageValue
	})
}

export async function userNotLoggedInBrowserActionClicked(){
	await chrome.tabs.create({
		url: SIGNIN_URL_CRX
	})
}

export function buildIncomingMessageContextMessage({timestamp} = {}){
	let contextMessage = 'MightyText';

	try{		
		if(timestamp && typeof timestamp == "string") contextMessage = cleanTimeDisplayPurposesOnlyTimeNoDay(timestamp, true) + ' ' + NOTIFICATION_SUFFIX;
	} catch(err){
		console.error("Error unable to build the incoming message context message string", err);		
	}
	
	return contextMessage;
}

export function cleanTimeDisplayPurposesOnlyTimeNoDay(datestring, should_convert_utc){
    if (should_convert_utc) {
        datestring = datestring + ' UTC';
    }
    
    var d = new Date(datestring);    
    
    return format(d, 'h:mm aaa');
}