import BrowserDetect from "./browser_detect.js"

class Analytics {
    static BASE_URL = "https://stats.mightytext.co"
    static recordEvent({name:tableName = "event_client_metric", options}){
        const browserDetect = new BrowserDetect();

        console.info("browserDetect", browserDetect);
        console
        let eventData = {//default values
            client: "crx",
            browser: browserDetect.browser,
            browser_version: browserDetect.version,
            os: browserDetect.OS,
            app_version: chrome.runtime.getManifest().version,
            session_id: "111"
        };    
        
        Object.assign(eventData, options);        

        const postData = {
            function: "addEvent",
            event: tableName,
            data: eventData
        }    
        
        fetch(Analytics.BASE_URL,{
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(postData)
        })
        .then(response => {
            if (!response.ok) {
                throw new Error('Network response was not ok ' + response.statusText);
            }
            return response.json(); // Parse the JSON response
        })
        .then(data => {
            console.log('Success:', data); // Handle the response data
        })
        .catch(error => {
            console.error('Error:', error); // Handle any errors
        });
    }
}

export default Analytics;