import { sub } from "date-fns"

import { colorConsole, getUserOS, determineIfNotifShouldRequireInteractionBasedOnOS, getLocalStorage, setLocalStorage, userNotLoggedInBrowserActionClicked, buildIncomingMessageContextMessage } from "../app_utils.js"
import { GLOBAL_SYSTEM_IDLE_STATUS_THRESHOLD_IN_SECONDS, WEBAPP_DOMAIN, BASE_URL, GLOBAL_MS_UNTIL_SHOW_NOT_LOGGED_IN_NOTIF_AGAIN } from "../constants.js"
import { getLocalizedAppString } from "./strings.js"
import Windows from "./windows.js"
import Analytics from "./analytics.js"
