    genericNotif({ notif_id: notifId, notif_sound: notifSound = true, auto_dismiss: autoDismiss = true, optional_notif_ref: optionalNotifRef }){
        const self = this;
        if(!notifId){
            colorConsole("Need to provide a notif id!", "red");
            return;
        }

        //notif sounds logic
        if(notifSound){
            self.playSound();//this is specific to incoming message notifications
        }
        //notif autodismiss logic
        if(autoDismiss){
            self.setId(notifId, optionalNotifRef);//checks the user's local storage setting
        }

        this.setId(notifId);    
    }

    static setAutoDismiss(notifId){    
        const notifAutoDismissSetting = chrome.storage.local.get(Notifications.AUTO_DISMISS_STORAGE_KEY);
		const removeDelay = 60 * 60 * 1000;//1 hour in ms (default value)
    
        if(notifId === Notifications.INITIAL_MMS_WAKEUP_NOTIF_ID){//initial mms warning notif        
            removeDelay = 10000;            
        } else if(notifAutoDismissSetting == "1"){            
            const userAutoDismissTimeSetting = parseInt(notifAutoDismissSetting);//not checking if this local storage key exists because it should be set in background on load of the CRX (without any user action) after checking that the user is cookie'd KL 9.7.16
            removeDelay = userAutoDismissTimeSetting * 1000;             
        }

        setTimeout(function(){
            chrome.notifications.clear(notifId);
            console.log(`notif clear after: ${removeDelay} milliseconds at: ${new Date()}`);
        }, removeDelay);
    }

    static playSound(){
        // A service worker has no DOM, so `new Audio(...)` is unavailable here.
        // Route playback to the offscreen document (html/background.html), which
        // has the user's sound settings in window.localStorage and plays the
        // tone via playNotificationTone() (see scripts/notifications.js).
        try{
            chrome.runtime.sendMessage({ playNotifSound: true }, () => {
                //read lastError so Chrome doesn't log "Unchecked runtime.lastError"
                //when the offscreen doc isn't listening; harmless otherwise.
                void chrome.runtime.lastError;
            });
        } catch(e){
            console.error("Unable to request notification sound playback", e);
        }
    }

    static notifCreated({notif_id: notifID, notif_sound = true, auto_dismiss = true}){
        if(!notifID){
            console.error("Missing notif id!");
            return false;
        }

        //play notif sound
        if(notif_sound)
            Notifications.playSound();//this is specific to incoming message notifications
        
        //should auto dismiss notif
        if(auto_dismiss)
            Notifications.setAutoDismiss(notifID);        

        Notifications.setId(notifID);    
    }

    static recordAnalyticsEvent({type, sub_type, count_in_session}){
        Analytics.recordEvent({options:{type, sub_type, count_in_session}})
    }

    async createUserNotLoggedInNotification(){
        const self = this;
        const dontShowNotLoggedInStorageKey = "crx_force_reload_no_signed_out_notif"
        const doNotShowUserNotLoggedInNotif = await getLocalStorage({key: dontShowNotLoggedInStorageKey})

        //We store this value when we restart the CRX. When the user starts the CRX with a good internet connection, but is not logged into MT. KL  Every hour they were getting a "user not logged in" notif, so this will prevent that.
        if(doNotShowUserNotLoggedInNotif == "1") return false;

        const options = await determineIfNotifShouldRequireInteractionBasedOnOS({
		    notifOptions: {
		        type : 'basic',
		        title: await getLocalizedAppString({key:"not_signed_in_title"}),
		        message: await getLocalizedAppString({key:"notif_signed_in_content"}),
		        iconUrl: '../img/48x48_MT_logo_boom_gradient_white.png',
		        priority: 2 //need this, otherwise Windows will make these silent and notifs will go straight to the system tray.
		    }
	    }),
	    notLoggedInNotifID = "user_not_logged_in";	    

        const notifId = await chrome.notifications.create(notLoggedInNotifID, options)

        console.log("created user_not_logged_in notif with the ID: " + notifId);
        
        await setLocalStorage({
            key: dontShowNotLoggedInStorageKey,
            value: "1",
            ttl: GLOBAL_MS_UNTIL_SHOW_NOT_LOGGED_IN_NOTIF_AGAIN
        });
        
		Notifications.recordAnalyticsEvent({
            type: 'notif-created',
            sub_type: 'user-not-logged-in'
		});

		Notifications.notifCreated({
			notif_id: notifId,
			auto_dismiss: false,
			notif_sound: true
		});
		
    }

